"""Stage 10: bigger human-style eval generated by Claude Haiku.

Goal: confirm the multi_gen 90% result on a larger, blind set in a writing
voice the model has never seen.

Different from Stage 7:
  - generator: anthropic/claude-haiku-4.5 (Stage 7 used gpt-4o-mini)
  - voice: 'short, casual, no-markdown comment from someone who skimmed the
    post and wants to react in one breath' (Stage 7 was 'Reddit reader')
  - n=100 pairs (Stage 7 was 50)
  - source posts: excluded posts that already appear in
      stage7/harder_eval.csv, overnight/cross_gen/_source_posts.csv,
      manual labelling.csv, or roberta_training/claude_test_labels.csv

Scored against:
  - poster_baseline (the 30k Qwen-3B model from the original poster)
  - v04_style_mix_qwen7b (poster baseline + 200 Qwen-7B aug)
  - multi_gen (Stage 9 winner: 1000 pairs across 5 LLMs)

Each pair is verified by a second Claude call (SAME / DIFFERENT).
"""
from __future__ import annotations

import argparse
import csv
import json
import os
import random
import sys
import time
from pathlib import Path
from typing import Any

import numpy as np
import pandas as pd
import torch
from transformers import AutoModelForSequenceClassification, AutoTokenizer

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from overnight.eval_common import (  # noqa: E402
    LABEL2ID, REPO, TEST_DOMAINS, save_json, _metrics_from_arrays, _batched_forward,
    load_human_csv, find_checkpoint,
)

OUT_DIR = REPO / "overnight" / "results" / "stage10"
OUT_CSV = OUT_DIR / "claude_human_eval.csv"


AGREE_PROMPT = """You just scrolled past a tweet/social-media post and an AI's explanation
of why it is or isn't hate speech. You agree with the AI. Write a 1-2 sentence
gut reaction in your OWN words. No markdown, no quotes, no preamble. Sound like
a tired person writing a comment on their phone -- could be a complete sentence
or a fragment. Use contractions, lowercase if you want.

Post: {post}
AI's explanation: {explanation}

Your reaction:"""

DISAGREE_PROMPT = """You just scrolled past a tweet/social-media post and an AI's explanation
of why it is or isn't hate speech. You DISAGREE -- you think the AI got it wrong
and the opposite verdict is correct. Write a 1-2 sentence gut reaction in your
OWN words. No markdown, no quotes, no preamble. Sound like a tired person writing
a comment on their phone. Use contractions, lowercase if you want.

Post: {post}
AI's explanation: {explanation}

Your reaction:"""

VERIFY_PROMPT = """Two reactions to the same social-media post. Do they reach the SAME conclusion
about whether the post is hate speech, or DIFFERENT conclusions?

Reaction A: {a}
Reaction B: {b}

Answer with exactly one word: SAME or DIFFERENT."""


def call_openrouter(model: str, prompt: str, max_tokens: int = 200,
                    temperature: float = 0.8) -> str:
    from openai import OpenAI
    client = OpenAI(
        base_url="https://openrouter.ai/api/v1",
        api_key=os.environ["OPENROUTER_API_KEY"],
    )
    resp = client.chat.completions.create(
        model=model,
        max_tokens=max_tokens,
        messages=[{"role": "user", "content": prompt}],
        temperature=temperature,
    )
    return resp.choices[0].message.content.strip()


def used_post_ids() -> set[str]:
    """Collect all post_ids and post texts that have appeared in any other
    eval/training set so we don't reuse them here."""
    used: set[str] = set()
    # Stage 9 cross-gen source posts (these are post UIDs)
    src = REPO / "overnight" / "cross_gen" / "_source_posts.csv"
    if src.exists():
        for v in pd.read_csv(src)["uid"].astype(str).tolist():
            used.add(v)
    # Stage 7 (matched by raw post text since no UID stored)
    s7 = REPO / "overnight" / "results" / "stage7" / "harder_eval.csv"
    if s7.exists():
        used.update(pd.read_csv(s7)["post"].astype(str).str.strip().tolist())
    return used


def sample_fresh_posts(n: int, seed: int = 43) -> pd.DataFrame:
    df = pd.read_csv(REPO / "reformulated_full.csv")
    df = df.dropna(subset=["explanation", "post", "domain", "uid"]).copy()
    df = df[df["domain"].isin(TEST_DOMAINS)].copy()
    df = df.drop_duplicates(subset=["uid"]).reset_index(drop=True)
    used = used_post_ids()
    df["uid"] = df["uid"].astype(str)
    df["post"] = df["post"].astype(str).str.strip()
    mask = (~df["uid"].isin(used)) & (~df["post"].isin(used))
    fresh = df[mask].reset_index(drop=True)
    print(f"[sample] fresh posts available: {len(fresh)} (out of {len(df)})", flush=True)
    rng = random.Random(seed)
    indices = rng.sample(range(len(fresh)), k=min(n, len(fresh)))
    return fresh.iloc[indices][["uid", "post", "explanation", "domain"]].reset_index(drop=True)


def generate(posts: pd.DataFrame, gen_model: str, verify_model: str) -> pd.DataFrame:
    rows = []
    for i, r in posts.iterrows():
        target = "equivalent" if i % 2 == 0 else "unequivalent"
        prompt = AGREE_PROMPT if target == "equivalent" else DISAGREE_PROMPT
        post = str(r["post"])[:1500]
        explanation = str(r["explanation"])[:1500]
        try:
            comment = call_openrouter(gen_model, prompt.format(post=post, explanation=explanation))
        except Exception as e:
            print(f"  [{i}] gen error: {e}", flush=True)
            continue
        try:
            v = call_openrouter(verify_model,
                                VERIFY_PROMPT.format(a=explanation, b=comment),
                                max_tokens=4, temperature=0)
        except Exception as e:
            print(f"  [{i}] verify error: {e}", flush=True)
            continue
        first = v.upper().split()[0] if v else ""
        verified = ("equivalent" if "SAME" in first else
                    "unequivalent" if "DIFFERENT" in first else None)
        if verified is None:
            print(f"  [{i}] verify garbage: {v!r}", flush=True)
            continue
        rows.append({
            "uid": r["uid"],
            "domain": r["domain"],
            "post": post,
            "explanation": explanation,
            "comment": comment,
            "label_target": target,
            "label_verified": verified,
            "target_matches_verified": target == verified,
        })
        if (i + 1) % 10 == 0:
            agreed = sum(1 for x in rows if x["target_matches_verified"])
            print(f"  [{i+1}/{len(posts)}] kept {len(rows)}, target/verified agree {agreed}/{len(rows)}",
                  flush=True)
    return pd.DataFrame(rows)


def score_ckpt(ckpt: Path, df: pd.DataFrame) -> dict[str, Any]:
    device = "cuda" if torch.cuda.is_available() else "cpu"
    tok = AutoTokenizer.from_pretrained(str(ckpt))
    model = AutoModelForSequenceClassification.from_pretrained(str(ckpt)).to(device)
    model.train(False)
    pairs = [(r["explanation"], r["comment"], LABEL2ID[r["label_verified"]])
             for _, r in df.iterrows() if r["label_verified"] in LABEL2ID]
    labels, preds, probs = _batched_forward(pairs, tok, model, device)
    return _metrics_from_arrays(labels, preds, probs)


def resolve_ckpt(name: str) -> Path | None:
    candidates = {
        "poster_baseline": REPO / "judge_finetune" / "runs" / "roberta_base" / "checkpoints" / "checkpoint-1576",
        "v04_style_mix_qwen7b": REPO / "overnight" / "runs" / "v04_style_mix_qwen7b" / "checkpoints",
        "multi_gen": REPO / "overnight" / "runs" / "stage9" / "multi_gen" / "checkpoints",
    }
    ck = candidates.get(name)
    if ck is None or not ck.exists():
        return None
    if (ck / "config.json").exists():
        return ck
    subs = sorted(ck.glob("checkpoint-*"))
    return subs[-1] if subs else None


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--n", type=int, default=100)
    parser.add_argument("--gen_model", default="anthropic/claude-haiku-4.5")
    parser.add_argument("--verify_model", default="anthropic/claude-haiku-4.5")
    parser.add_argument("--skip_generation", action="store_true")
    args = parser.parse_args()

    OUT_DIR.mkdir(parents=True, exist_ok=True)
    if args.skip_generation and OUT_CSV.exists():
        df = pd.read_csv(OUT_CSV)
        print(f"[stage10] reusing cached {OUT_CSV}  n={len(df)}", flush=True)
    else:
        if not os.environ.get("OPENROUTER_API_KEY"):
            print("[stage10] OPENROUTER_API_KEY not set; abort.")
            return 1
        posts = sample_fresh_posts(args.n)
        print(f"[stage10] generating {len(posts)} pairs via {args.gen_model} ...", flush=True)
        df = generate(posts, args.gen_model, args.verify_model)
        df.to_csv(OUT_CSV, index=False)
        print(f"[stage10] saved {OUT_CSV}  n_kept={len(df)}", flush=True)

    print(f"\n[stage10] label balance: {dict(df['label_verified'].value_counts())}")
    print(f"[stage10] target/verified agreement: "
          f"{df['target_matches_verified'].mean()*100:.1f}%", flush=True)

    targets = ["poster_baseline", "v04_style_mix_qwen7b", "multi_gen"]
    scores = {}
    for name in targets:
        ck = resolve_ckpt(name)
        if ck is None:
            print(f"[stage10] {name}: checkpoint not found; skipping")
            continue
        print(f"\n[stage10] scoring {name} -> {ck}", flush=True)
        m = score_ckpt(ck, df)
        scores[name] = m
        print(f"  n={m['n']}  acc={m['accuracy']:.3f}  f1={m['f1_macro']:.3f}  "
              f"eq={m.get('acc_equivalent',0):.2f}/uneq={m.get('acc_unequivalent',0):.2f}",
              flush=True)

    save_json(OUT_DIR / "scores.json", scores)

    # Append OVERNIGHTLOG
    log_path = REPO / "OVERNIGHTLOG.md"
    ts = time.strftime("%Y-%m-%d %H:%M")
    lines = [
        f"\n## {ts}  STAGE 10: bigger blind human eval (n={len(df)}, Claude Haiku voice)\n",
        f"Generated by `{args.gen_model}` on {len(df)} fresh OOD-test posts that don't "
        f"appear in stage 7 or stage 9 data. Verified by `{args.verify_model}`. "
        f"Different voice from Stage 7's GPT prompt (\"tired person writing on their phone\").",
        "",
        "| model | n | acc | f1_macro | eq / uneq |",
        "|---|---|---|---|---|",
    ]
    for name, m in scores.items():
        lines.append(f"| {name} | {m['n']} | {m['accuracy']*100:.1f}% | {m['f1_macro']:.3f} | "
                     f"{m.get('acc_equivalent',0)*100:.0f}%/{m.get('acc_unequivalent',0)*100:.0f}% |")
    lines.append("")
    with open(log_path, "a", encoding="utf-8") as f:
        f.write("\n".join(lines) + "\n")

    print("\n[stage10] done.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
